function gerarSenha() {
    const chars = '0123456789';
    let senha = '';

    for (let i = 0; i < 7; i++) {
        const indice = Math.floor(Math.random() * chars.length);
        senha += chars[indice];
    }

    return senha;
}

return {
  senhaAleatoria: gerarSenha()
}

